CREATE TABLE Agentic.AI_TARGET (ID VARCHAR(36) PRIMARY KEY, Environment VARCHAR(40), Namespace VARCHAR(128), ConnectionProfileVersion INTEGER, AllowedHost VARCHAR(512), CredentialReference VARCHAR(512), Enabled SMALLINT, Revision INTEGER, CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_PROMPT (ID VARCHAR(36) PRIMARY KEY, Name VARCHAR(200), Purpose VARCHAR(1000), CurrentVersion INTEGER, Owner VARCHAR(200), Lifecycle VARCHAR(30), Revision INTEGER, CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_PROMPT_VERSION (ID VARCHAR(36) PRIMARY KEY, PromptID VARCHAR(36), Version INTEGER, Content VARCHAR(32000), InputSchemaJSON VARCHAR(32000), OutputSchemaJSON VARCHAR(32000), Author VARCHAR(200), CreatedAt VARCHAR(40), UNIQUE (PromptID,Version));
CREATE TABLE Agentic.AI_MODEL_PROFILE_VERSION (ID VARCHAR(36) PRIMARY KEY, ProfileKey VARCHAR(100), Version INTEGER, Provider VARCHAR(100), ModelIdentifier VARCHAR(200), ParametersJSON VARCHAR(32000), CredentialReference VARCHAR(512), BudgetsJSON VARCHAR(32000), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_AGENT (ID VARCHAR(36) PRIMARY KEY, Name VARCHAR(200), Description VARCHAR(4000), Status VARCHAR(30), CurrentVersion INTEGER, CreatorIdentity VARCHAR(200), ParentProvenance VARCHAR(1000), Revision INTEGER, CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_AGENT_VERSION (ID VARCHAR(36) PRIMARY KEY, AgentID VARCHAR(36), Version INTEGER, PromptVersionID VARCHAR(36), ModelProfileVersionID VARCHAR(36), IterationLimit INTEGER, MemoryScopeJSON VARCHAR(32000), DelegationRulesJSON VARCHAR(32000), ResourceScopeJSON VARCHAR(32000), CreatedAt VARCHAR(40), UNIQUE (AgentID,Version));
CREATE TABLE Agentic.AI_TOOL (ID VARCHAR(36) PRIMARY KEY, StableKey VARCHAR(64) UNIQUE, Source VARCHAR(200), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_TOOL_VERSION (ID VARCHAR(36) PRIMARY KEY, StableKey VARCHAR(64), ContractHash VARCHAR(64), Method VARCHAR(10), PathTemplate VARCHAR(1000), Summary VARCHAR(4000), ParametersJSON VARCHAR(32000), RequestBodyJSON VARCHAR(32000), ResponsesJSON VARCHAR(32000), SecurityJSON VARCHAR(32000), Classification VARCHAR(20), Risk VARCHAR(40), Enabled SMALLINT, CreatedAt VARCHAR(40), UNIQUE (StableKey,ContractHash));
CREATE TABLE Agentic.AI_TOOL_POLICY_OVERRIDE (ID VARCHAR(36) PRIMARY KEY, ToolVersionID VARCHAR(36), Classification VARCHAR(20), PrivilegesJSON VARCHAR(32000), ScopeRulesJSON VARCHAR(32000), Reason VARCHAR(4000), Reviewer VARCHAR(200), ApprovalReference VARCHAR(100), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_AGENT_TOOL (ID VARCHAR(36) PRIMARY KEY, AgentVersionID VARCHAR(36), ToolVersionID VARCHAR(36), ResourceScopeJSON VARCHAR(32000), LimitsJSON VARCHAR(32000), UNIQUE (AgentVersionID,ToolVersionID));
CREATE TABLE Agentic.AI_AGENT_RELATION (ID VARCHAR(36) PRIMARY KEY, ParentAgentID VARCHAR(36), ChildAgentID VARCHAR(36), RelationType VARCHAR(40), OriginRunID VARCHAR(36), EffectiveScopeJSON VARCHAR(32000), ApprovalReference VARCHAR(100));
CREATE TABLE Agentic.AI_ROUTINE (ID VARCHAR(36) PRIMARY KEY, Name VARCHAR(200), CurrentVersion INTEGER, Status VARCHAR(30), Revision INTEGER, CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_ROUTINE_VERSION (ID VARCHAR(36) PRIMARY KEY, RoutineID VARCHAR(36), Version INTEGER, TriggerJSON VARCHAR(32000), ScheduleJSON VARCHAR(32000), Timezone VARCHAR(100), WorkflowJSON VARCHAR(32000), ConcurrencyPolicyJSON VARCHAR(32000), RetryPolicyJSON VARCHAR(32000), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_ROUTINE_STEP (ID VARCHAR(36) PRIMARY KEY, RoutineVersionID VARCHAR(36), StepKey VARCHAR(100), StepType VARCHAR(40), DependenciesJSON VARCHAR(32000), PinnedReferencesJSON VARCHAR(32000), InputMappingJSON VARCHAR(32000), OutputSchemaJSON VARCHAR(32000));
CREATE TABLE Agentic.AI_RUN (ID VARCHAR(36) PRIMARY KEY, ParentRunID VARCHAR(36), AgentVersionID VARCHAR(36), RoutineVersionID VARCHAR(36), WatchVersionID VARCHAR(36), TriggerType VARCHAR(40), State VARCHAR(30), StartedAt VARCHAR(40), EndedAt VARCHAR(40), BudgetsJSON VARCHAR(32000), FailureCategory VARCHAR(100));
CREATE TABLE Agentic.AI_RUN_MESSAGE (ID VARCHAR(36) PRIMARY KEY, RunID VARCHAR(36), SequenceNumber INTEGER, MessageRole VARCHAR(30), Content VARCHAR(32000), CreatedAt VARCHAR(40), RedactionMetadataJSON VARCHAR(32000), UNIQUE (RunID,SequenceNumber));
CREATE TABLE Agentic.AI_TOOL_EXECUTION (ID VARCHAR(36) PRIMARY KEY, RunID VARCHAR(36), ToolVersionID VARCHAR(36), ArgumentsHash VARCHAR(64), ProposalID VARCHAR(36), StartedAt VARCHAR(40), EndedAt VARCHAR(40), Status VARCHAR(30), EvidenceReference VARCHAR(512));
CREATE TABLE Agentic.AI_FINDING (ID VARCHAR(36) PRIMARY KEY, RunID VARCHAR(36), Severity VARCHAR(20), Confidence DECIMAL(8,6), ResourceIdentity VARCHAR(1000), ObservedAt VARCHAR(40), EvidenceReferencesJSON VARCHAR(32000), Explanation VARCHAR(32000), Recommendation VARCHAR(32000));
CREATE TABLE Agentic.AI_ACTION_PROPOSAL (ID VARCHAR(36), Revision INTEGER, OriginRunID VARCHAR(36), OriginAgentVersionID VARCHAR(36), ToolVersionID VARCHAR(36), SpecificationHash VARCHAR(64), PolicyVersion VARCHAR(100), TargetInstanceID VARCHAR(36), ConnectionProfileVersion INTEGER, Environment VARCHAR(40), Namespace VARCHAR(128), Method VARCHAR(10), ResolvedPath VARCHAR(1000), QueryParametersJSON VARCHAR(32000), SemanticHeadersJSON VARCHAR(32000), ContentType VARCHAR(200), BodyBytesBase64 VARCHAR(32000), BodySHA256 VARCHAR(64), SQLText VARCHAR(32000), TypedBindValuesJSON VARCHAR(32000), CredentialIdentityReference VARCHAR(512), CredentialVersion VARCHAR(100), ResourceIdentity VARCHAR(1000), BeforeStateJSON VARCHAR(32000), BeforeStateHash VARCHAR(64), PreconditionsJSON VARCHAR(32000), PreconditionStrategy VARCHAR(200), ExpectedEffect VARCHAR(4000), Risk VARCHAR(40), CreatedAt VARCHAR(40), ExpiresAt VARCHAR(40), IdempotencyKey VARCHAR(200), CanonicalizationVersion VARCHAR(50), ActionHash VARCHAR(64), State VARCHAR(30), PRIMARY KEY (ID,Revision));
CREATE TABLE Agentic.AI_APPROVAL (ID VARCHAR(200) PRIMARY KEY, ProposalID VARCHAR(36), ProposalRevision INTEGER, ActionHash VARCHAR(64), Actor VARCHAR(200), Decision VARCHAR(20), DecidedAt VARCHAR(40), Reason VARCHAR(1000), UNIQUE (ProposalID,ProposalRevision,Decision));
CREATE TABLE Agentic.AI_ACTION_EXECUTION (ID VARCHAR(36) PRIMARY KEY, ProposalID VARCHAR(36), ProposalRevision INTEGER, DispatchIdentity VARCHAR(100) UNIQUE, ClaimState VARCHAR(30), ResultJSON VARCHAR(32000), ReconciliationJSON VARCHAR(32000), PostconditionsJSON VARCHAR(32000), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_MEMORY (ID VARCHAR(36) PRIMARY KEY, Content VARCHAR(32000), Category VARCHAR(40), ScopeJSON VARCHAR(32000), ResourceIdentity VARCHAR(1000), SourceRunID VARCHAR(36), SourceFindingID VARCHAR(36), ObservedAt VARCHAR(40), Confidence DECIMAL(8,6), ExpiresAt VARCHAR(40), SupersededBy VARCHAR(36));
CREATE TABLE Agentic.AI_MEMORY_EMBEDDING (ID VARCHAR(36) PRIMARY KEY, MemoryID VARCHAR(36), ModelVersion VARCHAR(200), Dimension INTEGER, VectorJSON VARCHAR(32000), IndexingState VARCHAR(30));
CREATE TABLE Agentic.AI_ALERT_RULE (ID VARCHAR(36) PRIMARY KEY, Name VARCHAR(200), CurrentVersion INTEGER, Status VARCHAR(30), Revision INTEGER, CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_ALERT_RULE_VERSION (ID VARCHAR(36) PRIMARY KEY, AlertRuleID VARCHAR(36), Version INTEGER, Mission VARCHAR(32000), AgentVersionID VARCHAR(36), PromptVersionID VARCHAR(36), ScheduleJSON VARCHAR(32000), ScopeJSON VARCHAR(32000), SeverityRulesJSON VARCHAR(32000), CooldownJSON VARCHAR(32000), EscalationJSON VARCHAR(32000), CreatedAt VARCHAR(40));
CREATE TABLE Agentic.AI_ALERT_EVENT (ID VARCHAR(36) PRIMARY KEY, RuleID VARCHAR(36), FindingID VARCHAR(36), RunID VARCHAR(36), Fingerprint VARCHAR(64), Severity VARCHAR(20), Lifecycle VARCHAR(30), FirstSeenAt VARCHAR(40), LastSeenAt VARCHAR(40), OccurrenceCount INTEGER, Owner VARCHAR(200), AcknowledgementJSON VARCHAR(32000), SuppressionJSON VARCHAR(32000), ResolutionEvidenceJSON VARCHAR(32000), UNIQUE (RuleID,Fingerprint));
CREATE TABLE Agentic.AI_ALERT_DELIVERY (ID VARCHAR(36) PRIMARY KEY, AlertID VARCHAR(36), DestinationReference VARCHAR(512), DeliveryKey VARCHAR(200) UNIQUE, AttemptStatus VARCHAR(30), NextRetryAt VARCHAR(40));
CREATE TABLE Agentic.AI_JOB (ID VARCHAR(36) PRIMARY KEY, JobType VARCHAR(50), PayloadReference VARCHAR(512), DueAt VARCHAR(40), LeaseOwner VARCHAR(200), FencingToken INTEGER, Attempts INTEGER, Status VARCHAR(30), OccurrenceKey VARCHAR(200) UNIQUE);
CREATE TABLE Agentic.AI_AUDIT_EVENT (ID VARCHAR(36) PRIMARY KEY, Actor VARCHAR(200), Action VARCHAR(200), Entity VARCHAR(512), CorrelationID VARCHAR(100), OccurredAt VARCHAR(40), BeforeHash VARCHAR(64), AfterHash VARCHAR(64));
CREATE INDEX AgenticJobDue ON Agentic.AI_JOB (Status,DueAt);
CREATE INDEX AgenticRunHistory ON Agentic.AI_RUN (StartedAt,State);
CREATE INDEX AgenticProposalExpiry ON Agentic.AI_ACTION_PROPOSAL (State,ExpiresAt);
CREATE INDEX AgenticAlertLifecycle ON Agentic.AI_ALERT_EVENT (Lifecycle,Severity,LastSeenAt);
CREATE INDEX AgenticMemoryScope ON Agentic.AI_MEMORY (Category,ObservedAt);
